INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'edba1f8e-c3d8-445d-a086-e5b674441657', (SELECT idVocList FROM VocList WHERE title = 'Môi trường (environment)'), 'Tự nhiên (nature)', 'Energy', 'noun', 'Năng lượng', '/ˈɛnərʤi/', 'Ví dụ: As many experts has predicted, the world will soon face energy crises. (Như nhiều chuyên gia đã dự báo, thế giới sẽ sớm đối mặt với các cuộc khủng hoảng năng lượng)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '2e9bfd5b-070c-4927-91ba-da21ae208c7d', (SELECT idVocList FROM VocList WHERE title = 'Môi trường (environment)'), 'Tự nhiên (nature)', 'Flood', 'noun', 'Lũ lụt', '/flʌd/', 'Ví dụ: Many people have to evacuate because of the flood. (Rất nhiều người phải đi sơ tán vì trận lũ lụt)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
