INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '48ff86c6-9689-4bd7-8ed3-67128aebfe58', (SELECT idVocList FROM VocList WHERE title = 'Môi trường (environment)'), 'Tự nhiên (nature)', 'Hurricane', 'noun', 'Bão nhiệt đới – Tên gọi khi xảy ra tại Đại Tây Dương và Đông Bắc Thái Bình Dương', '/ˈhɜrəˌkeɪn./', 'Ví dụ: The island was damaged by a great hurricane last week. (Hòn đảo bị tàn phá bởi một cơn bão lớn vào tuần trước).', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '807644b5-7008-4050-9055-90d0922ba33d', (SELECT idVocList FROM VocList WHERE title = 'Môi trường (environment)'), 'Tự nhiên (nature)', 'Plastic', 'noun', 'Nhựa, chất dẻo', '/ˈplæstɪk/', 'Ví dụ: There are more and more plastic waste being thrown to seas and oceans. (Ngày càng nhiều rác thải nhựa được thải ra các biển và đại dương)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
