INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '2f597b57-e806-487e-806d-b12f5b81609e', (SELECT idVocList FROM VocList WHERE title = 'Môi trường (environment)'), 'Tự nhiên (nature)', 'Pollution', 'noun', 'Sự ô nhiễm', '/pəˈluʃən/', 'Ví dụ: Pollution is one of the most pressing problems in the world at the moment. (Ô nhiễm là một trong những vấn đề cấp bách nhất trên thế giới vào thời điểm hiện tại)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
