INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'c38087c0-3bb7-49e2-b7ef-a2bb279e8540', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Easy-going', 'adjective', 'Thoải mái', '/ˈizi-ˈgoʊɪŋ/', 'Ví dụ: His friends like him because he is an easy-going person. (Bạn bè thích anh ấy vì anh ấy là một người tính tình thoải mái)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'f52dcb5b-f8f3-4309-929d-7ffb1d1426b3', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Energetic', 'adjective', 'Tràn đầy năng lượng', 'ˌ/ɛnərˈʤɛtɪk/', 'Ví dụ: He is an energetic boy. He enjoys sports. (Cậu ấy là một cậu bé giàu năng lượng. Cậu ấy rất yêu thích thể thao)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
