INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'e0f703f0-074b-42d5-aa76-0d2b2bd6a58c', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Funny', 'adjective', 'Vui tính, hài hước', '/ˈfʌni/', 'Ví dụ: He is so funny and always tells hilarious jokes. (Anh ấy rất vui tính và luôn có những câu đùa hài hước)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '17512a2b-f076-4c2c-ae1e-792e51b20446', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Generous', 'adjective', 'Hào phóng', '/ˈʤɛnərəs/', 'Ví dụ: Being a generous man, he does not mind sharing his loaf of bread with a homeless man. (Là một người hào phóng, anh ấy không ngại chia sẻ ổ bánh mì của mình với một người vô gia cư)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
