INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '25d5d428-a511-4461-a1f4-d472abbc2aed', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Hard-working', 'adjective', 'Chăm chỉ, siêng năng', '/hɑrd-ˈwɜrkɪŋ/', 'Ví dụ: She is a hard-working employee. She is the first to come to the office in the morning and the last to go home in the afternoon. (Cô ấy là một nhân viên chăm chỉ. Cô ấy là người đầu tiên đến văn phòng vào buổi sáng và là người cuối cùng rời đi vào buổi chiều)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'ab3ff761-7cf0-40fe-871c-13af152c121f', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Honest', 'adjective', 'Thật thà, trung thực', '/ˈɑnəst/', 'Ví dụ: Since he is always honest and tells the truth, he gains many people’s trust. (Vì anh ấy luôn trung thực và nói sự thật nên anh ấy chiếm được lòng tin của rất nhiều người)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
