INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '70bb913d-f08d-4bc0-abc8-51df1f3ad0cc', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Lazy', 'adjective', 'Lười biếng', '/ˈleɪzi/', 'Ví dụ: She is too lazy to go out exercising in the weekend. (Cô ấy quá lười biếng để ra ngoài tập thể dục vào cuối tuần)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '4d1f13b4-ef84-450d-b055-3d75ef66657c', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Loyal', 'adjective', 'Trung thành', '/ˈlɔɪəl/', 'Ví dụ: Linda is known as a loyal friend who will never betray her friends. (Linda được biết đến như một người bạn trung thành, người mà sẽ không bao giờ phản bội bạn bè)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'da7f0dcd-f613-4643-a8ce-3a20d37071ee', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Nice', 'adjective', 'Tốt, tử tế', '/naɪs/', 'Ví dụ: I have nice colleagues at work who are willing to help me with difficult problems. (Tôi có những người đồng nghiệp tử tế luôn sẵn sàng giúp tôi với các vấn đề khó khăn tại nơi làm việc)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
