INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '85b25d55-002b-421a-a7dc-bf681c32367f', (SELECT idVocList FROM VocList WHERE title = 'Tính cách (personality)'), 'Con người (people)', 'Quiet', 'adjective', 'Im lặng, trầm tính', '/ˈkwaɪət/', 'Ví dụ: He is a quite person so people who have just met him may think that he is cold and distant. (Anh ấy là một người trầm tính nên những người mới gặp thường nghĩ anh ấy là một người lạnh lùng và xa cách)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
