INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'f115fcbd-9100-4563-b374-88c164062a4b', (SELECT idVocList FROM VocList WHERE title = 'Cảm xúc & cảm giác (emotions & feelings)'), 'Con người (people)', 'Angry', 'adjective', 'Tức giận, giận dữ', '/ˈæŋgri/', 'Ví dụ: Bob’s mom is very angry to hear that he cheated on his Math exam. (Mẹ của Bob rất tức giận khi biết tin Bob đã quay cóp trong bài kiểm tra Toán)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
