INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '02f8f11d-52ee-4a48-b67a-0227be08dcbb', (SELECT idVocList FROM VocList WHERE title = 'Cảm xúc & cảm giác (emotions & feelings)'), 'Con người (people)', 'Confused', 'adjective', 'Bối rối', '/kənˈfjuzd/', 'Ví dụ: Bella was a little confused when the teacher pronounced her name wrong. (Bella hơi bối rối khi cô giáo phát âm sai tên của cô ấy.)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
