INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'fe761042-0c24-41d3-969f-d6a19781d66a', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Artist', 'noun', 'Nghệ sĩ', '/ˈɑrtɪst/', 'Ví dụ: Artists are those with extremely high level of creativity. (Nghệ sĩ là những người có mức độ sáng tạo cực kì cao)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '746a2efa-79fc-4e3a-8f45-abb4cf018edd', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Artwork', 'noun', 'Tác phẩm nghệ thuật', '/ˈɑrˌtwɜrk/', 'Ví dụ: Twelve of his artworks have been delivered to Paris for an exhibition. (12 tác phẩm của anh ấy đã được chuyển tới Paris phục vụ cho một triển lãm)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '4cb7532a-f61a-43ae-93e9-8fae70baf354', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Audience', 'noun', 'Khán giả', '/ˈɔdiəns/', 'Ví dụ: The audience has arrived early and filled the concert hall. (Khán giả đã đến sớm và lấp đầy khán phòng)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '83b8cd81-88cf-48ed-9873-6fbb6d4bc4af', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Author', 'noun', 'Tác giả', '/ˈɔθər/', 'Ví dụ: Do you remember who is the author of ‘War and Peace’? (Cậu có nhớ ai là tác giả tiểu thuyết ‘Chiến tranh và Hòa bình’ không?)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '1f932c04-6944-44bb-9eeb-695d914225a5', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Band', 'noun', 'Ban nhạc', '/bænd/', 'Ví dụ: What is the name of your favorite band? (Tên ban nhạc yêu thích của cậu là gì?)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'b879974f-0133-4eca-9a9e-898f2a85cfe8', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Brush', 'noun', 'Cọ vẽ', '/brʌʃ/', 'Ví dụ: I need to buy some new brushes since the old ones are in bad condition. (Tớ cần mua thêm vài cây cọ vẽ mới vì những cái cũ đang trong tình trạng rất tệ)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '34d49ec7-4f58-4c4d-b209-5ca5ec3682a6', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Camera', 'noun', 'Máy ảnh', '/ˈkæmrə/', 'Ví dụ: Smile for the camera! (Cười lên trước máy ảnh nào!)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'c02ff93f-a666-446b-ad11-b9475867c0aa', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Canvas', 'noun', 'Vải bạt (để vẽ tranh sơn dầu)', '/ˈkænvəs/', 'Ví dụ: This is a blank canvas, you can draw anything you want here. (Đây là một mảnh vải bạt trắng, cậu có thể vẽ bất cứ thứ gì cậu muốn)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '3c2c2416-0bbc-4c4e-8ff0-6fcb0d38ce47', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Choir', 'noun', 'Dàn hợp xướng', '/ˈkwaɪər/', 'Ví dụ: I have attended the school’s choir for 3 years. (Tôi tham gia dàn hợp xướng của trường học 3 năm liền)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '04c1362b-c5e5-4196-a839-644cac18f6d8', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Clap', 'verb', 'Vỗ tay, hoan hô', '/klæp/', 'Ví dụ: The show was so good that he forgot to clap at the end of it. (Buổi diễn quá tuyệt đến mức anh ấy quên cả vỗ tay ở phần cuối chương trình)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '5cb9bb1f-68a4-48b4-9191-78b108486e9e', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Collection', 'noun', 'Bộ sưu tập', '/kəˈlɛkʃən/', 'Ví dụ: Gucci’s winter collection is remarkably wonderful. (Bộ sưu tập mùa đông của nhà mốt Gucci tuyệt vời một cách xuất sắc)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'b2cfcc14-7a9a-464c-815a-ca0e5c86867d', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Composer', 'noun', 'Nhà soạn nhạc', '/kəmˈpoʊzər/', 'Ví dụ: Mozart is a genius composer. (Mozart là một nhà soạn nhạc thiên tài)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '30761536-4c47-4baa-9cf8-32a4420c868a', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Concert', 'noun', 'Buổi trình diễn âm nhạc', '/kənˈsɜrt/', 'Ví dụ: I have 2 tickets for a My Tam concert this Sunday, do you want to come? (Tớ có 2 vé buổi diễn của Mỹ Tâm vào chủ nhật này, cậu có muốn đi cùng không?)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '51953e31-64da-44cb-b611-bb5a1a329762', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Creative', 'adjective', 'tính sáng tạo', '/kriˈeɪtɪv/', 'Ví dụ: You need to be creative in art. (Bạn cần phải sáng tạo trong nghệ thuật)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '2cd199ff-7e9c-4fb1-a339-df41429bd138', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Culture', 'noun', 'Văn hóa', '/ˈkʌlʧər/', 'Ví dụ: Other countries’ cultures never fail to amaze me. (Nền văn hóa của các quốc gia khác không bao giờ thất bại trong việc làm tôi trầm trồ ngạc nhiên)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '09878aa4-64ce-499d-baa2-e575c9acdc22', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Design', 'verb', 'Thiết kế', '/dɪˈzaɪn/', 'Ví dụ: He is designing a sample product. (Anh ấy đang thiết kế một sản phẩm mẫu)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'd0ee9c5c-12bd-494f-8a29-e7853566b5c1', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Drawing', 'noun', 'Bức vẽ', '/ˈdrɔɪŋ/', 'Ví dụ: He hangs his son’s drawing proudly on his wall. (Anh ấy treo bức vẽ của con trai mình lên tường một cách tự hào)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
