INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '8f956764-132a-4089-a5b3-cba4c5ccb0b1', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Film', 'noun', 'Bộ phim', '/fɪlm/', 'Ví dụ: We had dinner and watched a film together. (Chúng tôi ăn tối và xem một bộ phim cùng nhau)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '180eec6e-a79c-45e3-921a-f1cf98b00876', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Gallery', 'noun', 'Phòng triển lãm, trưng bày', '/ˈgæləri/', 'Ví dụ: He owns a personal gallery where he places all of his artworks. (Anh ấy sở hữu một phòng triển lãm cá nhân nơi mà anh ấy trưng bày tất cả các tác phẩm nghệ thuật của mình)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '386b5a5f-678b-473d-8f86-3c2a1b876dff', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Illustration', 'noun', 'Hình minh họa', '/ˌɪləˈstreɪʃən/', 'Ví dụ: This book has great and colorful illustration. (Quyển sách này có hình minh hoạt đẹp và đầy màu sắc)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'c28fd371-fba7-43b4-94ae-45d9840ee5fb', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Image', 'noun', 'Bức ảnh', '/ˈɪmɪʤ/', 'Ví dụ: Where did you find this image? (Cậu tìm thấy bức ảnh này ở đâu thế?)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '68334c20-39f2-4d2f-a51a-591e7c6c368c', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Inspiration', 'noun', 'Nguồn cảm hứng', '/ˌɪnspəˈreɪʃən/', 'Ví dụ: What is the inpiration for you to write this song? (Đâu là nguồn cảm hứng của chị khi viết bài hát này?)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'f6e98805-832e-42b4-acf0-8f609b553161', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Inspire', 'verb', 'Truyền cảm hứng', '/ɪnˈspaɪr/', 'Ví dụ: A good book inspires people to become better. (Một cuốn sách hay truyền cảm hứng để con người trở nên tốt đẹp hơn)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '7f662110-a0fa-42b3-89ab-7b2c47b849cb', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Literature', 'noun', 'Văn học, văn chương', '/ˈlɪtərəʧər/', 'Ví dụ: Literature nurtures the souls. (Văn chương nuôi dưỡng tâm hồn)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '9d881d47-5f9e-4225-98df-1ab5189e8ba1', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Masterpiece', 'noun', 'Kiệt tác', '/ˈmæstərˌpis/', 'Ví dụ: “Monalisa” is a well-known masterpiece of Leonardo Da Vinci. (‘Monalisa’ là một kiệt tác nổi tiếng của danh họa Leonardo Da Vinci)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'a75117ab-7854-49d9-ac02-61b2d7b7f4b1', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Model', 'noun', 'Mẫu (vẽ), người mẫu', '/ˈmɑdəl/', 'Ví dụ: She needs 2 female models for a nude painting. (Cô ấy cần 2 người mẫu nữ để vẽ một bức họa khỏa thân)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '1c3121a7-8501-44dd-a245-c2d43ed72466', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Movie', 'noun', 'Bộ phim', '/ˈmuvi/', 'Ví dụ: This is the worst movie I have ever seen. (Đây là bộ phim tệ nhất tôi đã từng xem)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '2b912cee-19f4-4b29-b637-82e9949c92b4', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Music', 'noun', 'Âm nhạc', '/ˈmjuzɪk/', 'Ví dụ: Everyone loves music. (Tất cả mọi người đều yêu âm nhạc)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'e9ea5eda-25d9-4b0b-9902-3a82c4845233', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Musical Instrument', 'noun', 'Nhạc cụ', '/ˈmjuzɪkəl ˈɪnstrəmənt/', 'Ví dụ: Have you considered learning a musical instrument? (Cậu đã cân nhắc việc học chơi một nhạc cụ mới chưa?)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'e872b1a6-8e47-45dc-9de1-9592a8b27fad', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Novel', 'noun', 'Tiểu thuyết', '/ˈnɑvəl/', 'Ví dụ: ‘Les Misérables’ is a classical novel that everyone should read at least once in their life. (‘Những người khốn khổ’ là tiểu thuyết cổ điển mà ai cũng nên đọc ít nhất một lần trong đời)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '7658862e-7a96-441b-9979-7c29d7a8ac32', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Painting', 'noun', 'Bức vẽ, bức tranh', '/ˈpeɪntɪŋ/', 'Ví dụ: A painting that is considered “beautiful” can cost up to millions of US $. (Một bức tranh được cho là “đẹp” có thể có giá lên tới hàng triệu đô la Mỹ)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( 'e40af801-5856-47f0-9587-ae48e8e92dc9', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Paper', 'noun', 'Tờ giấy', '/ˈpeɪpər/', 'Ví dụ: We will need thicker paper for watercolor drawing. (Chúng ta sẽ cần loại giấy dày hơn để vẽ màu nước)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '01854721-7fcc-4302-9d92-8040d4c3d5f7', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Pattern', 'noun', 'Họa tiết', '/ˈpætərn/', 'Ví dụ: She likes the pattern on the sweater she has been given. (Cô ấy thích họa tiết trên chiếc áo len cô ấy được tặng)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
