INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '6c1d0785-29a0-45b1-9b94-bc6cec36c7cd', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Photo', 'noun', 'Bức ảnh', '/ˈfoʊˌtoʊ/', 'Ví dụ: He took great photos. (Anh ấy chụp những bức ảnh rất tuyệt vời)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '3cd24151-8176-47d1-a495-506b765937fe', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Photographer', 'noun', 'Nhiếp ảnh gia', '/fəˈtɑgrəfər/', 'Ví dụ: The photographer guides the model to make the best poses. (Nhiếp ảnh gia hướng dẫn người mẫu tạo những dáng đẹp nhất)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
