INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
( '39e8faa3-24de-4433-a65b-3958ec93d4c8', (SELECT idVocList FROM VocList WHERE title = 'Nghệ thuật (arts)'), 'Nghệ thuật (arts)', 'Poetry', 'noun', 'Thơ ca', '/ˈpoʊətri/', 'Ví dụ: Poetry is the voice of the heart. (Thơ ca là tiếng lòng)', 0);
INSERT INTO Vocabularies (idVoc, idList, topic, engWord, wordType, meaning, pronunciation, example, status) VALUES
